contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, uint256 amount) public payable {
        require(sender != address(0), "sender zero");
        require(amount > 0, "amount zero");
        require(address(this).balance >= amount, "insufficient balance");

        // Impersonate sender for the deposit call.
        // On the first call from this address, the low-level call is attempted and reverts;
        // if the sender is itself a contract with a receive/fallback that calls back, it
        // would deposit, but that requires the sender to be under the tester's control.
        (bool ok, ) = sender.call{value: amount}(abi.encodeWithSignature("Deposit()"));
        require(ok, "deposit failed");

        uint256 senderBalance = c.balances(sender);
        uint256 contractBalance = address(c).balance;

        assert(senderBalance == amount && contractBalance == amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint minSum, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);
        require(depositAmount <= 1000);

        c.SetMinSum(minSum);
        c.Initialized();

        c.Deposit{value: depositAmount}();

        uint beforeBalance = c.balances(address(this));

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = c.balances(address(this));

        assert(
            (beforeBalance < c.MinSum() || beforeBalance < collectAmount)
                ? (reverted && afterBalance == beforeBalance)
                : (!reverted && afterBalance == beforeBalance - collectAmount)
        );
    }

    receive() external payable {}
}

