contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount + collectAmount);

        uint contractBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;
        uint callerBalanceBefore = c.balances(address(this));

        c.Deposit{value: depositAmount}();

        uint totalBalanceAfterDeposit = c.balances(address(this)) + address(this).balance;
        uint totalEtherAfterDeposit = address(c).balance;
        assert(totalBalanceAfterDeposit == totalEtherAfterDeposit);

        bool collectSucceeded = false;
        bool collectReverted = false;
        uint balanceBeforeCollect = c.balances(address(this));
        uint etherBeforeCollect = address(c).balance;
        uint receivedBeforeCollect = address(this).balance;

        try c.Collect(collectAmount) {
            collectSucceeded = true;
        } catch {
            collectReverted = true;
        }

        uint balanceAfterCollect = c.balances(address(this));
        uint etherAfterCollect = address(c).balance;
        uint receivedAfterCollect = address(this).balance;

        if (collectSucceeded) {
            uint balanceDecrease = balanceBeforeCollect - balanceAfterCollect;
            uint receivedIncrease = receivedAfterCollect >= receivedBeforeCollect ? receivedAfterCollect - receivedBeforeCollect : 0;
            assert(balanceDecrease == collectAmount && receivedIncrease == collectAmount);
            assert(balanceAfterCollect + receivedAfterCollect == etherAfterCollect);
        } else {
            assert(collectReverted);
            assert(balanceAfterCollect == balanceBeforeCollect && etherAfterCollect == etherBeforeCollect);
        }
    }

    receive() external payable {}
}

