contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint dep, uint col) public payable {
        require(dep > 0);
        require(col <= dep);
        require(address(this).balance >= dep);
        c.SetMinSum(0);
        c.Initialized();
        uint beforeBal = c.balances(address(this));
        c.Deposit{value: dep}();
        uint midBal = c.balances(address(this));
        bool reverted;
        try c.Collect(col) { reverted = false; } catch { reverted = true; }
        uint afterBal = c.balances(address(this));
        if (!reverted) {
            assert(midBal - afterBal == col && afterBal == beforeBal && midBal == beforeBal + dep);
        } else {
            assert(afterBal == midBal);
        }
    }
    receive() external payable {}
}

